```rust
use std::fs;
use std::path::Path;
use serde::Deserialize;
use thiserror::Error;

#[derive(Debug, Deserialize)]
struct Config {
    name: String,
    port: u16,
}

#[derive(Debug, Error)]
enum ConfigError {
    #[error("не удалось прочитать файл {path}: {source}")]
    Io {
        path: String,
        #[source]
        source: std::io::Error,
    },
    #[error("некорректный JSON в {path}: {source}")]
    Parse {
        path: String,
        #[source]
        source: serde_json::Error,
    },
}

fn load_config(path: &Path) -> Result<Config, ConfigError> {
    let raw = fs::read_to_string(path).map_err(|source| ConfigError::Io {
        path: path.display().to_string(),
        source,
    })?;

    let config = serde_json::from_str::<Config>(&raw).map_err(|source| ConfigError::Parse {
        path: path.display().to_string(),
        source,
    })?;

    Ok(config)
}

fn main() {
    match load_config(Path::new("config.json")) {
        Ok(cfg) => println!("Загружено: {} на порту {}", cfg.name, cfg.port),
        Err(e) => eprintln!("Ошибка: {e}"),
    }
}
```

Разбор подхода: `fs::read_to_string` возвращает `io::Error`, который оборачивается в вариант `Io` с сохранением исходной ошибки через `#[source]` — это позволяет строить цепочки причин. `serde_json::from_str` возвращает `serde_json::Error`, который содержит номер строки и столбца, что критично для диагностики. Использование `thiserror` даёт автоматическую реализацию `Display` и `std::error::Error`, а `?` распространяет ошибку наверх без паники. В `main` ошибка обрабатывается через `match`, но допустимо также вернуть `Result<(), Box<dyn Error>>` из `main`.

