    use std::io::Cursor;

    #[test]
    fn parses_valid_json_from_str() {
        let json = br#"{"port": 8080, "name": "app"}"#;
        let cfg = parse_config(&json[..]).unwrap();
        assert_eq!(cfg, Config { port: 8080, name: "app".into() });
    }

    #[test]
    fn parses_from_cursor() {
        let data = br#"{"port": 1, "name": "x"}"#.to_vec();
        let cfg = parse_config(Cursor::new(data)).unwrap();
        assert_eq!(cfg.port, 1);
    }

    #[test]
    fn rejects_invalid_json() {
        let json = br#"{"port": "not a number"}"#;
        assert!(parse_config(&json[..]).is_err());
    }

