    fn loads_from_temp_file() {
        use std::io::Write;
        let mut tmp = tempfile::NamedTempFile::new().unwrap();
        write!(tmp, r#"{{"port": 9090, "name": "tmp"}}"#).unwrap();
        let cfg = load_config(tmp.path()).unwrap();
        assert_eq!(cfg.port, 9090);
    }
}
